import {cascaderListApi} from "@/api/product";

export default {
  name: 'c_classify',
  props: {
    configObj: {
      type: Object
    },
    configNme: {
      type: String
    },
    number: {
      type: null
    },
  },
  data() {
    return {
      defaults: {},
      configData: {},
      props: {emitPath: false, multiple: true, checkStrictly: true},
      treeSelect: []
    }
  },
  mounted() {
    this.$nextTick(() => {
      this.defaults = this.configObj
      this.configData = this.configObj[this.configNme]
      this.goodsCategory();
    })
  },
  watch: {
    configObj: {
      handler(nVal, oVal) {
        this.defaults = nVal
        this.configData = nVal[this.configNme]
      },
      deep: true
    }
  },
  methods: {
    sliderChange() {
      this.$emit('getConfig', {name: 'classlfy'})
    },
    goodsCategory() {
      cascaderListApi(1)
          .then((res) => {
            this.treeSelect = res.data;
          })
          .catch((res) => {
            this.$Message.error(res.msg);
          });
    }
  }
}
